from pathlib import Path
import hashlib,json
p=Path(__file__).resolve().parent
common=(p/'early-prompt.txt').read_text(encoding='utf-8').split('\n\n',1)[1]
for name,target,instruction in [('early','south','EDIT the supplied SOUTH FRONT pose by making a SMALL20degree turn toward VIEWER LEFT. The result must remain nearly front-facing: both eyes fully visible, nose slightly left of facial center, both shoulders and chest front visible, left/right knee separation almost unchanged. Rotate head, chest, hips and case consistently only a LITTLE from this target. Keep face mainly facing viewer, never a45degree diagonal or profile. This supplied image is the single EDIT TARGET; preserve its identity/material/composition and proportions.'),('late','west','EDIT the supplied WEST LEFT PROFILE pose by making a SMALL20degree turn TOWARD the viewer/front. The result must remain nearly left-facing: mostly profile nose pointing left, only a slim far-eye/cheek visible, a little more front chest/case than the target. Turn head/chest/hips/case consistently only a LITTLE toward viewer. Never a45degree diagonal or front pose. This supplied image is the single EDIT TARGET; preserve its identity/material/composition and proportions.')]:
    prompt=instruction+'\n\n'+common+'\nDo not grow or shrink the character. Preserve exact original reference crown29.7percent and ground87.5percent on canvas. Both boot soles remain at target baseline. Same subdued master grade, no new luminous patches.'
    (p/(name+'-v2-prompt.txt')).write_text(prompt+'\n',encoding='utf-8')
    files=[p/(target+'-reference.png'),p/(name+'-v2-prompt.txt'),Path(__file__)]
    (p/(name+'-v2-inputs.json')).write_text(json.dumps({'preCallSha256':{f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in files},'editTarget':target+'-reference.png','targetAngleDegrees':20 if name=='early' else 70,'sourceCanvas':[256,256],'standingRuler':148,'pivot':[128,224],'selected':False,'scope':'Single nearest-cardinal edit to break midpoint copying; all whole-body geometry/material require review.'},indent=2)+'\n',encoding='utf-8')
print('Two nearest-cardinal single-target edit prompts frozen; original rejected raws/pack retained.')
